package net.officefloor.hq.app.project;

import jakarta.validation.Valid;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@RequestMapping("/api/projects")
public class ProjectController {

    private final ProjectService service;

    public ProjectController(ProjectService service) {
        this.service = service;
    }

    @GetMapping
    public List<ProjectResponse> list(@RequestParam(defaultValue = "false") boolean includeArchived,
            @RequestParam(required = false) Long tagId, @RequestParam(required = false) ProjectStatus status) {
        return service.list(includeArchived, tagId, status);
    }

    @PutMapping("/order")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    public void reorder(@Valid @RequestBody ProjectOrderRequest request) {
        service.reorder(request.ids());
    }

    @GetMapping("/{id}")
    public ProjectResponse get(@PathVariable Long id) {
        return service.get(id);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public ProjectResponse create(@Valid @RequestBody ProjectRequest request) {
        return service.create(request);
    }

    @PutMapping("/{id}/status")
    public ProjectResponse changeStatus(@PathVariable Long id, @Valid @RequestBody ProjectStatusRequest request) {
        return service.changeStatus(id, request.status());
    }

    @PutMapping("/{id}/billable")
    public ProjectResponse setBillable(@PathVariable Long id, @Valid @RequestBody ProjectBillableRequest request) {
        return service.setBillable(id, request.billable());
    }

    @PutMapping("/{id}/dates")
    public ProjectResponse setDates(@PathVariable Long id, @RequestBody ProjectDatesRequest request) {
        return service.setDates(id, request.startDate(), request.endDate());
    }

    @PutMapping("/{id}/file-ref")
    public ProjectResponse setFileRef(@PathVariable Long id, @Valid @RequestBody ProjectFileRefRequest request) {
        return service.setFileRef(id, request.fileRef());
    }

    @PutMapping("/{id}/category")
    public ProjectResponse setCategory(@PathVariable Long id, @Valid @RequestBody ProjectCategoryRequest request) {
        return service.setCategory(id, request.category());
    }

    @GetMapping("/{id}/budget")
    public ProjectBudgetResponse budget(@PathVariable Long id) {
        return service.budget(id);
    }

    @PutMapping("/{id}/budget")
    public ProjectBudgetResponse setBudget(@PathVariable Long id, @Valid @RequestBody ProjectBudgetRequest request) {
        return service.setBudget(id, request.budget());
    }

    @PostMapping("/{id}/close")
    public ProjectResponse close(@PathVariable Long id) {
        return service.close(id);
    }

    @PostMapping("/{id}/reopen")
    public ProjectResponse reopen(@PathVariable Long id) {
        return service.reopen(id);
    }

    @PostMapping("/{id}/archive")
    public ProjectResponse archive(@PathVariable Long id) {
        return service.archive(id);
    }

    @PostMapping("/{id}/restore")
    public ProjectResponse restore(@PathVariable Long id) {
        return service.restore(id);
    }
}
package net.officefloor.hq.app.project;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Iterator;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.creditnote.CreditNoteRepository;
import net.officefloor.hq.app.invoice.Invoice;
import net.officefloor.hq.app.invoice.InvoiceRepository;
import net.officefloor.hq.app.invoice.InvoiceStatus;
import net.officefloor.hq.app.payment.PaymentRepository;
import java.util.Locale;
import java.util.Objects;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class ProjectService {

    private final ProjectRepository projects;
    private final ClientRepository clients;
    private final InvoiceRepository invoices;
    private final PaymentRepository payments;
    private final CreditNoteRepository creditNotes;
    private final Audit audit;

    public ProjectService(ProjectRepository projects, ClientRepository clients, InvoiceRepository invoices,
            PaymentRepository payments, CreditNoteRepository creditNotes, Audit audit) {
        this.projects = projects;
        this.clients = clients;
        this.invoices = invoices;
        this.payments = payments;
        this.creditNotes = creditNotes;
        this.audit = audit;
    }

    /**
     * The projects, leaving out archived ones unless they are asked for, and only those carrying the
     * given tag and at the given status when those are given.
     */
    @Transactional(readOnly = true)
    public List<ProjectResponse> list(boolean includeArchived, Long tagId, ProjectStatus status) {
        List<Project> found;
        if (tagId == null) {
            found = includeArchived ? projects.findAllWithClient() : projects.findActiveWithClient();
        } else {
            found = includeArchived ? projects.findAllByTagIdWithClient(tagId)
                    : projects.findActiveByTagIdWithClient(tagId);
        }
        return respond(found.stream().filter(p -> status == null || p.getStatus() == status).toList());
    }

    /**
     * A client's projects: only those under way (active status and not archived) unless all of them,
     * including finished, on hold and archived ones, are asked for.
     */
    @Transactional(readOnly = true)
    public List<ProjectResponse> listForClient(Long clientId, boolean includeAll) {
        if (!clients.existsById(clientId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client");
        }
        if (includeAll) {
            return respond(projects.findAllByClientIdWithClient(clientId));
        }
        return respond(projects.findActiveByClientIdWithClient(clientId).stream()
                .filter(p -> p.getStatus() == ProjectStatus.ACTIVE).toList());
    }

    @Transactional(readOnly = true)
    public ProjectResponse get(Long id) {
        return projects.findByIdWithClient(id).map(this::respond)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
    }

    /** Adds a project; its code, trimmed and upper-cased, must not already belong to another project. */
    @Transactional
    public ProjectResponse create(ProjectRequest request) {
        Client client = clients.findById(request.clientId())
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown client"));
        String code = request.code().trim().toUpperCase(Locale.ROOT);
        if (projects.existsByCode(code)) {
            throw codeTaken();
        }
        Project project = new Project(request.name().trim(), code, client);
        project.setSortOrder(projects.maxSortOrder() + 1);
        if (request.status() != null) {
            project.setStatus(request.status());
        }
        if (request.description() != null && !request.description().isBlank()) {
            project.setDescription(request.description().trim());
        }
        if (request.billable() != null) {
            project.setBillable(request.billable());
        }
        try {
            return respond(projects.saveAndFlush(project));
        } catch (DataIntegrityViolationException e) {
            // Lost a race with a concurrent add of the same code; the unique constraint caught it.
            if (String.valueOf(e.getMessage()).toUpperCase().contains("PROJECT_CODE_UQ")) {
                throw codeTaken();
            }
            throw e;
        }
    }

    /**
     * Puts the given projects into the given order and keeps it. The ids are the list as the user sees
     * it (possibly filtered); they are rearranged among the places they already hold, so projects not
     * in the list keep their places.
     */
    @Transactional
    public void reorder(List<Long> ids) {
        if (new HashSet<>(ids).size() != ids.size()) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "A job is listed more than once");
        }
        List<Project> all = projects.findAllOrdered();
        Map<Long, Project> byId = new HashMap<>();
        all.forEach(p -> byId.put(p.getId(), p));
        if (!byId.keySet().containsAll(ids)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Unknown job");
        }
        Set<Long> moved = Set.copyOf(ids);
        Iterator<Long> next = ids.iterator();
        int position = 1;
        for (Project slot : all) {
            Project placed = moved.contains(slot.getId()) ? byId.get(next.next()) : slot;
            placed.setSortOrder(position++);
        }
        audit.record("PROJECTS_REORDERED ids=" + ids.stream().map(String::valueOf).collect(Collectors.joining(",")));
    }

    private static final BigDecimal ZERO = BigDecimal.ZERO.setScale(2);

    /** The given projects, each with what is still owed on it. */
    private List<ProjectResponse> respond(List<Project> found) {
        Map<Long, BigDecimal> owed = outstandingByProject();
        return found.stream().map(p -> ProjectResponse.from(p, owed.getOrDefault(p.getId(), ZERO))).toList();
    }

    private ProjectResponse respond(Project project) {
        return ProjectResponse.from(project, outstandingByProject().getOrDefault(project.getId(), ZERO));
    }

    /**
     * What is still owed on each project: what is left to pay on its sent invoices that are not yet fully
     * paid, after the payments and credit notes against them. Projects owing nothing are left out.
     */
    private Map<Long, BigDecimal> outstandingByProject() {
        List<InvoiceStatus> owing = List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL);
        Map<Long, BigDecimal> owed = new HashMap<>();
        invoices.sumAmountByStatusInPerProject(owing).forEach(t -> owed.merge(t.getProjectId(), t.getTotal(),
                BigDecimal::add));
        payments.sumAmountByInvoiceStatusInPerProject(owing).forEach(t -> owed.merge(t.getProjectId(),
                t.getTotal().negate(), BigDecimal::add));
        creditNotes.sumAmountByInvoiceStatusInPerProject(owing).forEach(t -> owed.merge(t.getProjectId(),
                t.getTotal().negate(), BigDecimal::add));
        owed.replaceAll((id, amount) -> amount.setScale(2, RoundingMode.HALF_UP));
        return owed;
    }

    private static ResponseStatusException codeTaken() {
        return new ResponseStatusException(HttpStatus.CONFLICT, "A job with this code already exists");
    }

    /** Invoices count as invoiced once sent; drafts have not been invoiced yet. */
    private static final List<InvoiceStatus> INVOICED =
            List.of(InvoiceStatus.SENT, InvoiceStatus.PARTIAL, InvoiceStatus.PAID);

    /**
     * The project's budget, how much has been invoiced against it (the invoices' totals before tax, as
     * the tax is not the job's to spend), and what is left.
     */
    @Transactional(readOnly = true)
    public ProjectBudgetResponse budget(Long id) {
        Project project = projects.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        return budgetOf(project);
    }

    /** Sets (or, given none, clears) a project's budget, recording the change in the audit log. */
    @Transactional
    public ProjectBudgetResponse setBudget(Long id, BigDecimal budget) {
        Project project = projects.findById(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        BigDecimal scaled = budget == null ? null : budget.setScale(2, RoundingMode.HALF_UP);
        BigDecimal current = project.getBudget();
        boolean changed = scaled == null ? current != null : current == null || current.compareTo(scaled) != 0;
        if (changed) {
            project.setBudget(scaled);
            projects.flush();
            audit.record("PROJECT_BUDGET_SET id=" + id + " budget=" + (scaled == null ? "none" : scaled.toPlainString()));
        }
        return budgetOf(project);
    }

    private ProjectBudgetResponse budgetOf(Project project) {
        BigDecimal invoiced = invoices.findByProjectIdOrderById(project.getId()).stream()
                .filter(i -> INVOICED.contains(i.getStatus()))
                .map(Invoice::getTotalExTax)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        return ProjectBudgetResponse.of(project.getBudget(), invoiced);
    }

    /** Marks a project active, on hold or finished, recording the change in the audit log. */
    @Transactional
    public ProjectResponse changeStatus(Long id, ProjectStatus status) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (project.getStatus() != status) {
            project.setStatus(status);
            projects.flush();
            audit.record("PROJECT_STATUS_CHANGED id=" + id + " status=" + status);
        }
        return respond(project);
    }

    /** Marks a project billable or non-billable, recording the change in the audit log. */
    @Transactional
    public ProjectResponse setBillable(Long id, boolean billable) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (project.isBillable() != billable) {
            project.setBillable(billable);
            projects.flush();
            audit.record("PROJECT_BILLABLE_SET id=" + id + " billable=" + billable);
        }
        return respond(project);
    }

    /**
     * Sets (or, given none, clears) a job's start and end dates, recording the change in the audit log.
     * The end may not be before the start.
     */
    @Transactional
    public ProjectResponse setDates(Long id, LocalDate startDate, LocalDate endDate) {
        if (startDate != null && endDate != null && endDate.isBefore(startDate)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The end date may not be before the start date");
        }
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (!Objects.equals(project.getStartDate(), startDate) || !Objects.equals(project.getEndDate(), endDate)) {
            project.setDates(startDate, endDate);
            projects.flush();
            audit.record("PROJECT_DATES_SET id=" + id + " start=" + (startDate == null ? "none" : startDate)
                    + " end=" + (endDate == null ? "none" : endDate));
        }
        return respond(project);
    }

    /** Notes (or, given none, clears) a job's file reference, recording the change in the audit log. */
    @Transactional
    public ProjectResponse setFileRef(Long id, String fileRef) {
        String ref = fileRef == null || fileRef.isBlank() ? null : fileRef.trim();
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (!Objects.equals(project.getFileRef(), ref)) {
            project.setFileRef(ref);
            projects.flush();
            audit.record("PROJECT_FILE_REF_SET id=" + id + " fileRef=" + (ref == null ? "none" : ref));
        }
        return respond(project);
    }

    /** Puts a job into (or, given none, takes it out of) a category, recording the change in the audit log. */
    @Transactional
    public ProjectResponse setCategory(Long id, String category) {
        String value = category == null || category.isBlank() ? null : category.trim();
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (!Objects.equals(project.getCategory(), value)) {
            project.setCategory(value);
            projects.flush();
            audit.record("PROJECT_CATEGORY_SET id=" + id + " category=" + (value == null ? "none" : value));
        }
        return respond(project);
    }

    /** Closes a job so no new invoice can be raised on it, recording the closing in the audit log. */
    @Transactional
    public ProjectResponse close(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (!project.isClosed()) {
            project.setClosed(true);
            projects.flush();
            audit.record("PROJECT_CLOSED id=" + id);
        }
        return respond(project);
    }

    /** Reopens a closed job so invoices can be raised on it again, recording the reopening in the audit log. */
    @Transactional
    public ProjectResponse reopen(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (project.isClosed()) {
            project.setClosed(false);
            projects.flush();
            audit.record("PROJECT_REOPENED id=" + id);
        }
        return respond(project);
    }

    /**
     * Archives a project: it drops off the project lists but is kept, with its tasks and invoices,
     * and the archiving is recorded in the audit log.
     */
    @Transactional
    public ProjectResponse archive(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (!project.isArchived()) {
            project.setArchived(true);
            projects.flush();
            audit.record("PROJECT_ARCHIVED id=" + id);
        }
        return respond(project);
    }

    /** Brings an archived project back onto the project lists, recording it in the audit log. */
    @Transactional
    public ProjectResponse restore(Long id) {
        Project project = projects.findByIdWithClient(id)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown job"));
        if (project.isArchived()) {
            project.setArchived(false);
            projects.flush();
            audit.record("PROJECT_RESTORED id=" + id);
        }
        return respond(project);
    }
}
package net.officefloor.hq.app.project;

import java.util.List;
import java.util.Optional;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface ProjectRepository extends JpaRepository<Project, Long> {

    /** All projects with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client ORDER BY p.sortOrder, p.id")
    List<Project> findAllWithClient();

    /** All projects not archived, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.archived = false ORDER BY p.sortOrder, p.id")
    List<Project> findActiveWithClient();

    /** All projects carrying a tag, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client JOIN p.tags t WHERE t.id = :tagId ORDER BY p.sortOrder, p.id")
    List<Project> findAllByTagIdWithClient(Long tagId);

    /** All projects not archived carrying a tag, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client JOIN p.tags t WHERE t.id = :tagId"
            + " AND p.archived = false ORDER BY p.sortOrder, p.id")
    List<Project> findActiveByTagIdWithClient(Long tagId);

    /** A client's projects not archived, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client c WHERE c.id = :clientId AND p.archived = false"
            + " ORDER BY p.sortOrder, p.id")
    List<Project> findActiveByClientIdWithClient(Long clientId);

    /** All of a client's projects, archived or not, with their client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client c WHERE c.id = :clientId ORDER BY p.sortOrder, p.id")
    List<Project> findAllByClientIdWithClient(Long clientId);

    /**
     * Projects not archived whose name contains the text, ignoring case, with their client loaded in the
     * same query.
     */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.archived = false"
            + " AND LOWER(p.name) LIKE LOWER(CONCAT('%', :text, '%')) ESCAPE '\\' ORDER BY p.sortOrder, p.id")
    List<Project> searchActiveByNameWithClient(String text);

    /** One project with its client loaded in the same query. */
    @Query("SELECT p FROM Project p JOIN FETCH p.client WHERE p.id = :id")
    Optional<Project> findByIdWithClient(Long id);

    /** The highest position any project holds, or 0 when there are none. */
    @Query("SELECT COALESCE(MAX(p.sortOrder), 0) FROM Project p")
    int maxSortOrder();

    /** All projects, archived or not, in their kept order. */
    @Query("SELECT p FROM Project p ORDER BY p.sortOrder, p.id")
    List<Project> findAllOrdered();

    /** Whether any project, archived or not, already has the code. */
    boolean existsByCode(String code);

    /** How many projects a client has. */
    long countByClientId(Long clientId);

    /** Whether any invoice has been raised against the project. */
    @Query("SELECT COUNT(i) > 0 FROM Invoice i WHERE i.project.id = :id")
    boolean hasInvoices(Long id);
}
package net.officefloor.hq.app.project;

/** Where a project stands: being worked on, paused, or done. */
public enum ProjectStatus {
    ACTIVE,
    ON_HOLD,
    FINISHED
}
-- Projects are archived rather than deleted: an archived project drops off the project lists but
-- is kept, with its tasks and invoices, and can be brought back.
ALTER TABLE project ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- A project is marked active, on hold or finished; existing projects are taken to be active.
ALTER TABLE project ADD COLUMN status VARCHAR(16) DEFAULT 'ACTIVE' NOT NULL;

ALTER TABLE project ADD CONSTRAINT project_status_valid CHECK (status IN ('ACTIVE', 'ON_HOLD', 'FINISHED'));

