export class Projects {
  private readonly service = inject(ProjectService);
  private readonly clientService = inject(ClientService);
  private readonly tagService = inject(TagService);

  protected readonly projects = signal<Project[]>([]);
  protected readonly clients = signal<Client[]>([]);
  protected readonly saving = signal(false);
  protected readonly saveError = signal<string | null>(null);
  protected readonly deleting = signal<number | null>(null);
  protected readonly deleteError = signal<string | null>(null);
  protected readonly showArchived = signal(false);
  protected readonly tags = signal<Tag[]>([]);
  protected readonly tagFilter = signal<number | null>(null);
  protected readonly statusFilter = signal<ProjectStatus | null>(null);
  protected readonly statuses = PROJECT_STATUSES;
  protected readonly reordering = signal(false);
  protected readonly reorderError = signal<string | null>(null);
  protected readonly reorderStatus = signal('');
  protected readonly dragIndex = signal<number | null>(null);
  protected readonly dropIndex = signal<number | null>(null);

  protected readonly form = inject(NonNullableFormBuilder).group({
    name: ['', [Validators.required, Validators.maxLength(255)]],
    code: ['', [Validators.required, Validators.pattern(/^\s*[A-Za-z0-9-]{1,20}\s*$/)]],
    description: ['', Validators.maxLength(500)],
    clientId: ['', Validators.required],
    status: ['ACTIVE' as ProjectStatus, Validators.required],
  });

  constructor() {
    this.load();
    this.clientService.list().subscribe((list) => this.clients.set(list));
    this.tagService.list().subscribe((list) => this.tags.set(list));
  }

  protected showError(field: 'name' | 'code' | 'description' | 'clientId'): boolean {
    const control = this.form.controls[field];
    return control.invalid && (control.touched || control.dirty);
  }

  protected submit(): void {
    if (this.form.invalid || !this.form.getRawValue().name.trim()) {
      this.form.markAllAsTouched();
      return;
    }
    const { name, code, description, clientId, status } = this.form.getRawValue();
    this.saving.set(true);
    this.saveError.set(null);
    const project = {
      name: name.trim(),
      code: code.trim().toUpperCase(),
      description: description.trim() || null,
      clientId: Number(clientId),
      status,
    };
    this.service.create(project).subscribe({
      next: (created) => {
        // A new project carries no tags, so it only belongs on a list not filtered by tag, and only
        // when its status matches any status filter.
        if (this.tagFilter() === null && this.matchesStatusFilter(created)) {
          this.projects.update((list) => [...list, created]);
        }
        this.form.reset();
        this.saving.set(false);
      },
      error: (err: HttpErrorResponse) => {
        if (err.status === 409) {
          // The server owns uniqueness; flag the code field until it is changed.
          const codeControl = this.form.controls.code;
          codeControl.setErrors({ taken: true });
          codeControl.markAsTouched();
        } else {
          this.saveError.set('Could not save the job. Please try again.');
        }
        this.saving.set(false);
      },
    });
  }

  protected toggleArchived(): void {
    this.showArchived.update((show) => !show);
    this.load();
  }

  protected filterByTag(value: string): void {
    this.tagFilter.set(value === '' ? null : Number(value));
    this.load();
  }

  protected filterByStatus(value: string): void {
    this.statusFilter.set(value === '' ? null : (value as ProjectStatus));
    this.load();
  }

  protected changeStatus(project: Project, status: string): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.changeStatus(project.id, status as ProjectStatus).subscribe({
      next: (changed) => {
        // A project moved off the filtered status drops off the list.
        this.projects.update((list) =>
          this.matchesStatusFilter(changed)
            ? list.map((p) => (p.id === changed.id ? changed : p))
            : list.filter((p) => p.id !== changed.id),
        );
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not change the status of ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  protected archive(project: Project): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.archive(project.id).subscribe({
      next: (archived) => {
        this.projects.update((list) =>
          this.showArchived()
            ? list.map((p) => (p.id === archived.id ? archived : p))
            : list.filter((p) => p.id !== archived.id),
        );
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not archive ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  protected restore(project: Project): void {
    this.deleting.set(project.id);
    this.deleteError.set(null);
    this.service.restore(project.id).subscribe({
      next: (restored) => {
        this.projects.update((list) => list.map((p) => (p.id === restored.id ? restored : p)));
        this.deleting.set(null);
      },
      error: () => {
        this.deleteError.set(`Could not restore ${project.name}. Please try again.`);
        this.deleting.set(null);
      },
    });
  }

  protected dragStart(event: DragEvent, index: number): void {
    this.dragIndex.set(index);
    if (event.dataTransfer) {
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', String(index));
    }
  }

  protected dragOver(event: DragEvent, index: number): void {
    if (this.dragIndex() === null) {
      return;
    }
    event.preventDefault();
    if (event.dataTransfer) {
      event.dataTransfer.dropEffect = 'move';
    }
    this.dropIndex.set(index);
  }

  protected drop(event: DragEvent, index: number): void {
    event.preventDefault();
    const from = this.dragIndex();
    this.dragEnd();
    if (from !== null) {
      this.move(from, index);
    }
  }

  protected dragEnd(): void {
    this.dragIndex.set(null);
    this.dropIndex.set(null);
  }

  /** Moves the job at one place in the list to another and keeps the new order. */
  protected move(from: number, to: number): void {
    const before = this.projects();
    if (from === to || to < 0 || to >= before.length || this.reordering()) {
      return;
    }
    const after = [...before];
    const [moved] = after.splice(from, 1);
    after.splice(to, 0, moved);
    this.projects.set(after);
    this.reordering.set(true);
    this.reorderError.set(null);
    this.service.reorder(after.map((p) => p.id)).subscribe({
      next: () => {
        this.reorderStatus.set(`${moved.name} moved to position ${to + 1} of ${after.length}.`);
        this.reordering.set(false);
      },
      error: () => {
        this.projects.set(before);
        this.reorderError.set(`Could not move ${moved.name}. Please try again.`);
        this.reordering.set(false);
      },
    });
  }

  private matchesStatusFilter(project: Project): boolean {
    const status = this.statusFilter();
    return status === null || project.status === status;
  }

  private load(): void {
    this.service
      .list(this.showArchived(), this.tagFilter(), this.statusFilter())
      .subscribe((list) => this.projects.set(list));
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { CurrencyCode } from '../clients/client.service';

export type ProjectStatus = 'ACTIVE' | 'ON_HOLD' | 'FINISHED';

/** The statuses a project can be marked with, in the order they are offered. */
export const PROJECT_STATUSES: { value: ProjectStatus; label: string }[] = [
  { value: 'ACTIVE', label: 'Active' },
  { value: 'ON_HOLD', label: 'On hold' },
  { value: 'FINISHED', label: 'Finished' },
];

export interface Project {
  id: number;
  name: string;
  /** Short reference code, unique across jobs; null for jobs added before codes existed. */
  code: string | null;
  clientId: number;
  clientName: string;
  archived: boolean;
  status: ProjectStatus;
  /** The currency of the client the job is for. */
  currency: CurrencyCode;
  /** A short description of the work; null when none was given. */
  description: string | null;
  /** Whether the work is charged to the client; internal work is non-billable. */
  billable: boolean;
  /** Whether the job is closed; no new invoice can be raised on a closed job. */
  closed: boolean;
  /** The day work on the job starts (YYYY-MM-DD); null when not set. */
  startDate: string | null;
  /** The day work on the job ends (YYYY-MM-DD); null when not set. */
  endDate: string | null;
  /** A reference to a file kept elsewhere for the job (e.g. a document number); null when none was noted. */
  fileRef: string | null;
  /** The category the job is put into (e.g. "Web"); null when it has none. */
  category: string | null;
  /** What is still owed on the job's sent invoices after payments and credit notes; null where not worked out. */
  outstanding: number | null;
}

/** A project's budget, what has been invoiced against it, and what is left; null when no budget is set. */
export interface ProjectBudget {
  budget: number | null;
  invoiced: number;
  remaining: number | null;
}

export interface NewProject {
  name: string;
  code: string;
  clientId: number;
  status: ProjectStatus;
  description: string | null;
}

@Injectable({ providedIn: 'root' })
export class ProjectService {
  private readonly http = inject(HttpClient);

  list(
    includeArchived = false,
    tagId: number | null = null,
    status: ProjectStatus | null = null,
  ): Observable<Project[]> {
    const params: Record<string, string | number | boolean> = { includeArchived };
    if (tagId !== null) {
      params['tagId'] = tagId;
    }
    if (status !== null) {
      params['status'] = status;
    }
    return this.http.get<Project[]>('/api/projects', { params });
  }

  listForClient(clientId: number, includeAll = false): Observable<Project[]> {
    return this.http.get<Project[]>(`/api/clients/${clientId}/projects`, {
      params: { includeAll },
    });
  }

  /** Puts the jobs into the given order (ids first to last) and keeps it. */
  reorder(ids: number[]): Observable<void> {
    return this.http.put<void>('/api/projects/order', { ids });
  }

  get(id: number): Observable<Project> {
    return this.http.get<Project>(`/api/projects/${id}`);
  }

  create(project: NewProject): Observable<Project> {
    return this.http.post<Project>('/api/projects', project);
  }

  changeStatus(id: number, status: ProjectStatus): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/status`, { status });
  }

  setBillable(id: number, billable: boolean): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/billable`, { billable });
  }

  setDates(id: number, startDate: string | null, endDate: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/dates`, { startDate, endDate });
  }

  setFileRef(id: number, fileRef: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/file-ref`, { fileRef });
  }

  setCategory(id: number, category: string | null): Observable<Project> {
    return this.http.put<Project>(`/api/projects/${id}/category`, { category });
  }

  budget(id: number): Observable<ProjectBudget> {
    return this.http.get<ProjectBudget>(`/api/projects/${id}/budget`);
  }

  setBudget(id: number, budget: number | null): Observable<ProjectBudget> {
    return this.http.put<ProjectBudget>(`/api/projects/${id}/budget`, { budget });
  }

  close(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/close`, null);
  }

  reopen(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/reopen`, null);
  }

  archive(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/archive`, null);
  }

  restore(id: number): Observable<Project> {
    return this.http.post<Project>(`/api/projects/${id}/restore`, null);
  }
}

